mapper.select:
SELECT announcement.id AS announcement_id, COUNT(recipient.actor_id) AS recipient_total, COUNT(receipt.actor_id) AS read_total FROM oa_announcement announcement LEFT JOIN oa_announcement_recipient recipient ON recipient.tenant_id = announcement.tenant_id AND recipient.announcement_id = announcement.id LEFT JOIN oa_announcement_read_receipt receipt ON receipt.tenant_id = recipient.tenant_id AND receipt.announcement_id = recipient.announcement_id AND receipt.actor_id = recipient.actor_id WHERE announcement.tenant_id = #{tenantId} AND announcement.id IN
#{announcementId}
GROUP BY announcement.id
